PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: -- At-bottom
        IF CallUp AND DoorClosed THEN
            State := 1;
        ELSIF NOT DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    1: -- Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF CallDown OR AtTop OR Not DoorClosed THEN
            State := 3;
        END_IF;

    2: -- At-top
        IF CallDown AND DoorClosed THEN
            State := 3;
        ELSIF Not DoorClosed THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    3: -- Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF CallUp OR AtBottom OR Not DoorClosed THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

