END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH AND Level >= LIQ_MIN THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
    State := 3;
ELSIF State = 3 AND Ticks >= PT_REACT THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW AND Level >= LIQ_MIN THEN
    State := 0;
ELSIF State = 1 OR State = 4 THEN
    FillValve := TRUE;
ELSE
    FillValve := FALSE;
END_IF;

CASE State OF
    0:
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    3:
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    4:
        Heater := FALSE;
