    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF TON1.Q THEN
            State := 4;
        ELSE
            TON1(IN := TRUE, PT := PT_REACT);
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;

    ELSE:
        State := 0;
END_CASE;

// Ensure fill and drain valves never open together
FillValve := FillValve AND NOT DrainValve;
DrainValve := DrainValve AND NOT FillValve;

