    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW AND Level >= LIQ_MIN THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
