    T1 : TON;
END_VAR

CASE State OF
    0: -- Off
        IF StartPB AND EStop THEN
            State := 1;
            MainK := TRUE;
            StarK := TRUE;
            DeltaK := FALSE;
        END_IF;

    1: -- Star
        IF T1.Q THEN
            State := 2;
            StarK := FALSE;
            DeltaK := TRUE;
        ELSE
            T1(IN := TRUE, PT := PT_STAR);
        END_IF;

    2: -- Delta
        IF StopPB OR NOT EStop THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        END_IF;
END_CASE;

