PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;
    PrevDemand := Demand;

    IF Demand THEN
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT;
    PrevDemand : BOOL;
END_VAR

// Edge detection for demand end
PrevDemand := Demand;

// Emergency stop overrides everything
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Alternate lead on demand end
    IF NOT Demand AND PrevDemand THEN
        Lead := 1 - Lead; // Toggle lead
    END_IF;

    // Assign pumps based on lead state
    Pump1 := (Lead = 0) AND Demand;
    Pump2 := (Lead = 1) AND Demand;
END_IF;

END_PROGRAM

