    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND NOT StopPB THEN
    CASE State OF
        0: 
            IF T2.Q THEN
                State := 3;
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
            ELSIF T1.Q THEN
                State := 2;
                C1 := FALSE;
                C2 := TRUE;
                C3 := TRUE;
            ELSE
                State := 1;
                C1 := FALSE;
                C2 := FALSE;
                C3 := TRUE;
                T1(IN := TRUE, PT := T#2s);
            END_IF;
        1: 
            State := 2;
            C1 := FALSE;
            C2 := TRUE;
            C3 := TRUE;
            T2(IN := TRUE, PT := T#2s);
        2: 
            State := 3;
            C1 := TRUE;
            C2 := TRUE;
            C3 := TRUE;
        3: ;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Done : BOOL;
    Count : INT;
    PrevTrigger : BOOL;
END_VAR

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSIF Trigger AND NOT PrevTrigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
    IF Count >= 3 THEN
        Done := TRUE;
    END_IF;
END_IF;

PrevTrigger := Trigger;
Done := (Count >= 3);
END_PROGRAM

